-- 支付查询管理入口，不新增支付渠道密钥配置，不授予角色，可重复执行。
BEGIN;
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time) SELECT '交易管理',0,3,'trade',NULL,1,0,'M','0','1','','shopping','migration',CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE parent_id=0 AND path='trade' AND menu_type='M');
SET @trade_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='trade' AND menu_type='M' ORDER BY menu_id LIMIT 1);
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time) SELECT '支付单',@trade_root,20,'payments','trade/payment/index',1,0,'C','0','1','trade:payment:list','shopping','migration',CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE parent_id=@trade_root AND path='payments' AND menu_type='C');
SET @payment_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@trade_root AND path='payments' AND menu_type='C' ORDER BY menu_id LIMIT 1);
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time) SELECT '查看详情',@payment_page,1,'',NULL,1,0,'F','0','1','trade:payment:query','shopping','migration',CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE parent_id=@payment_page AND perms='trade:payment:query' AND menu_type='F');
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time) SELECT '支付退单',@trade_root,21,'payment-refunds','trade/payment-refund/index',1,0,'C','0','1','trade:payment-refund:list','shopping','migration',CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE parent_id=@trade_root AND path='payment-refunds' AND menu_type='C');
SET @payment_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@trade_root AND path='payment-refunds' AND menu_type='C' ORDER BY menu_id LIMIT 1);
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time) SELECT '查看详情',@payment_page,1,'',NULL,1,0,'F','0','1','trade:payment-refund:query','shopping','migration',CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE parent_id=@payment_page AND perms='trade:payment-refund:query' AND menu_type='F');
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time) SELECT '支付配置',@trade_root,22,'payment-channels','trade/payment-channel/index',1,0,'C','0','1','trade:payment-channel:list','shopping','migration',CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE parent_id=@trade_root AND path='payment-channels' AND menu_type='C');
COMMIT;
